public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());
        int[] a = new int[N];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            a[i] = Integer.parseInt(st.nextToken());
        }
        Arrays.sort(a);

        final long INF = Long.MAX_VALUE / 4;
        long[] dp_prev2 = new long[K + 1];
        long[] dp_prev = new long[K + 1];
        long[] dp_curr = new long[K + 1];

        Arrays.fill(dp_prev2, INF);
        dp_prev2[0] = 0;

        Arrays.fill(dp_prev, INF);
        dp_prev[0] = 0;

        for (int i = 2; i <= N; i++) {
            Arrays.fill(dp_curr, INF);
            int maxJ = Math.min(K, i / 2);
            for (int j = 0; j <= maxJ; j++) {
                // skip the i-th doll
                dp_curr[j] = dp_prev[j];

                // use dolls i-1 and i (1-based) as the two smallest of a triple
                if (j >= 1) {
                    int Mj = N - 3 * K + 3 * j - 1;
                    if (i <= Mj) {
                        long cost = (long) (a[i - 1] - a[i - 2]) * (a[i - 1] - a[i - 2]);
                        if (dp_prev2[j - 1] != INF) {
                            dp_curr[j] = Math.min(dp_curr[j], dp_prev2[j - 1] + cost);
                        }
                    }
                }
            }
            // shift rows
            long[] temp = dp_prev2;
            dp_prev2 = dp_prev;
            dp_prev = dp_curr;
            dp_curr = temp;
        }

        System.out.println(dp_prev[K]);
    }
}
